const text = $input.first().json.telegram.message.text;
const results = { command: "UNKNOWN", data: {}, telegram: $input.first().json.telegram };

// Helper function to capitalize the first letter of each word
const toTitleCase = (str) => {
    if (!str) return str;
    return str.toLowerCase().split(' ').map(word => 
        word.charAt(0).toUpperCase() + word.slice(1)
    ).join(' ');
};

// Define Regex Map
const patterns = {
    CREATE: /^(?:create|new)\s+recipe(?:\s+for)?\s+"?(?<name>.+?)"?\s+(?:that\s+)?yields\s+(?<yield>\d+(\.\d+)?)\s*(?<unit>\w+)(?:\s+(?:for|at)\s*(?:[â‚¬$Â£]\s*)?(?<price>\d+(\.\d+)?))?$/i,
    ADD_ITEM: /^(?:add|put)\s+"?(?<quantity>\d+(\.\d+)?)"?\s*(?<unit>\w+)\s+"?(?<ingredient_name>.+?)"?\s+(?:to|in)\s+(?:the\s+)?\s*"?(?<recipe_name>[^"]+)"?\s*$/i,
   REMOVE_ITEM: /^(?:remove|delete|take out)\s+"?(?<ingredient_name>.+?)"?\s+(?:from|of)\s+(?:the\s+)?\s*"?(?<recipe_name>[^".]+)"?\.?\s*$/i,
    COOK: /^(?:made|cooked|used recipe)\s+(?<yield_made>\d+)\s+"?(?<recipe_name>.+?)"?\s*$/i,
    COST_CHECK: /^(?:how\s+much\s+(?:does|is))\s+"?(?<recipe_name>.+?)"?\s+(?:recipe\s+)?cost\?*\s*$/i,
    REPORT: /^(?:show|list|display)\s+(?:all\s+)?recipes\?*$|^(?:recipe|product)\s+report\?*$/i,
    DETAILS: /^(?:show|display| what\s+are|tell\s+me)\s+(?:the\s+)?(?:recipe\s+details|recipe\s+info|recipe\s+components)\s+(?:for|of)\s+"?(?<recipe_name>.+?)"?\s*$|^(?:what(?:\'s| is)\s+in)\s+the\s+"?(?<recipe_name_q>.+?)"?\s*\?*$/i,
    SET_INSTR: /^(?:set|add|update)\s+instructions\s+(?:for|to)\s+"?(?<recipe_name>.+?)"?\s*:\s*(?<instructions>.+)$/i,
  DELETE_RECIPE: /^(?:delete|remove|destroy)\s+recipe\s+"?(?<recipe_name>.+?)"?\s*$/i,
};

// Loop through and find match
for (const [cmd, regex] of Object.entries(patterns)) {
    const match = text.match(regex);
    if (match) {
        results.command = cmd;
        let data = { ...match.groups };

        // Handle the 'or' group for DETAILS
        if (cmd === 'DETAILS' && !data.recipe_name) {
            data.recipe_name = data.recipe_name_q;
        }

        // Apply Capitalization to relevant fields
        if (data.name) data.name = toTitleCase(data.name);
        if (data.recipe_name) data.recipe_name = toTitleCase(data.recipe_name);
        if (data.ingredient_name) data.ingredient_name = toTitleCase(data.ingredient_name);
        if (data.unit) data.unit = toTitleCase(data.unit);

        results.data = data;
        break;
    }
}

return results;

